 Check(LibrarySearch.Matches(song,"001 Country","wil 4x4")&&LibrarySearch.Matches(song,"001 Country","2024 country"),"Mehrere Wortteile feldübergreifend");Check(LibrarySearch.Matches(new Song{Artist="AC/DC",Title="Thunderstruck",Source="ACDC.mp3"},"","acdc thunder"),"AC/DC und ACDC werden gefunden");Check(LibrarySearch.FindVoice(new[]{song},new[]{"Lenny Wilson vier mal vier mal you"})==song,"Lainey/Lenny und 4x4xU sprachlich zugeordnet");Check(LibrarySearch.FindVoice(new[]{song,song.Copy()},new[]{"Lainey Wilson 4x4xU"})==null,"Mehrdeutige Sprachbefehle starten keinen zufälligen Titel");bool play;Check(LibrarySearch.PlayTerm("Bitte spiele mir das Lied 4x4xU!",out play)=="4x4xU"&&play,"Sprachbefehl vom Suchtext getrennt");
 var copy=song.Copy();copy.Year="2025";copy.Genre="Testgenre";copy.Comment="Geändert äöü";copy.Artist="Neue Künstlerin";string path=Path.Combine(root,"tags.mp3");MediaMetadata.WriteCopy(copy,"Testalbum",path,()=>{});var reread=MediaMetadata.Read(path);Check(reread.Artist==copy.Artist&&reread.Year==copy.Year&&reread.Genre==copy.Genre&&reread.Comment==copy.Comment&&reread.Album=="Testalbum","Bearbeitete vollständige Metadaten in Dateikopie geprüft");Check(before.SequenceEqual(File.ReadAllBytes(file)),"Originaldatei bleibt bytegleich");string cancelled=Path.Combine(root,"cancel.mp3");bool failed=false;try{int n=0;MediaMetadata.WriteCopy(song,song.Album,cancelled,()=>{if(++n>1)throw new OperationCanceledException();});}catch(OperationCanceledException){failed=true;}Check(failed&&!File.Exists(cancelled),"Abbruch hinterlässt keine teilweise geschriebene Datei");
 string m3u=Path.Combine(root,"liste.m3u8");PlaylistFiles.Save(m3u,new[]{song,copy});copy.Source=path;PlaylistFiles.Save(m3u,new[]{song,copy});var loaded=PlaylistFiles.Load(m3u,new[]{song,copy});Check(loaded.Count==2&&loaded[0]==song&&loaded[1]==copy,"UTF-8-Wiedergabeliste erhält Reihenfolge und Zuordnung");
