 var project=new Project();project.Folders.Add(new BoxFolder{Name="000 Country",Theme="Country",Songs=new List<Song>{song,copy}});string json=Path.Combine(root,"project.musikbox.json");Storage.Save(project,json);var restored=Storage.Load(json);Check(restored.Folders[0].Songs[1].Year=="2025"&&restored.Folders[0].Songs[1].Comment=="Geändert äöü","Projekt speichert neue Metadaten verlustfrei");
 Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);using(var view=new MainView(Path.Combine(root,"layout.json"))){var controller=new Controller(view,Path.Combine(root,"backups"),new Playback(new PlaybackTestDevice()));Call(controller,"ReplaceProject",project,null,true);Check(view.WindowState==FormWindowState.Maximized,"Maximierter Start vor Show im nativen Fenster konfiguriert");view.Show();Application.DoEvents();if(Environment.OSVersion.Platform!=PlatformID.Win32NT){view.WindowState=FormWindowState.Normal;view.Bounds=new Rectangle(0,0,1400,920);}Application.DoEvents();Check(view.Songs.Rows.Count==2&&view.Songs.Columns.Contains("Jahr")&&view.Songs.Columns.Contains("Ordner"),"Studio-Titelliste zeigt vollständige Metadaten");Check(!view.Tools.Visible&&view.Tools.Parent==null,"Keine zusaetzliche Menuezeile in der Referenzansicht");var center=(Control)typeof(MainView).GetField("studioCenter",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(view);var right=(Control)typeof(MainView).GetField("studioRight",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(view);Check(center.Left==236&&center.Top==74&&right.Width==315,"Spaltenbreiten und kompakter Arbeitsbeginn entsprechen der Vorgabe");Check(view.PlayerPane.Height==72&&view.PlayerPane.Bottom==view.ClientSize.Height-10,"Playerposition und kompakte Hoehe entsprechen der Vorgabe");Check(!view.TagEditor.ChangeArtist.Visible&&!view.TagEditor.ChangeTitle.Visible&&!view.TagEditor.ChangeAlbum.Visible,"Metadaten ohne zusaetzliche sichtbare Aenderungs-Checkboxen");view.SearchBox.Text="Neue Künstlerin";Application.DoEvents();Check(view.Songs.Rows.Count==1,"Native Suche filtert die Bibliothek");view.SearchBox.Clear();view.Songs.ClearSelection();view.Songs.Rows[0].Selected=true;view.Songs.CurrentCell=view.Songs.Rows[0].Cells[0];Application.DoEvents();view.TagEditor.Comment.Text="Noch nicht bestaetigt";view.SearchBox.Text="nicht vorhanden";Check(((Project)typeof(Controller).GetField("p",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(controller)).Folders[0].Songs[0].Comment=="Noch nicht bestaetigt","Ausstehende Metadaten bleiben beim Suchwechsel erhalten");view.SearchBox.Clear();view.InvokeCommand("Rückgängig");view.LibraryMode="Alben";Call(controller,"PopulateLibrary");Check(view.Groups.Rows.Count==1,"Native Albenansicht gruppiert korrekt");view.LibraryMode="Titel";Call(controller,"PopulateLibrary");view.Songs.ClearSelection();view.Songs.Rows[0].Selected=true;view.Songs.CurrentCell=view.Songs.Rows[0].Cells[0];Application.DoEvents();view.TagEditor.Year.Text="2026";Call(controller,"CommitSideTags");Check(((Project)typeof(Controller).GetField("p",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(controller)).Folders[0].Songs[0].Year=="2026","Jahränderung aus nativer Seitenleiste übernommen");view.InvokeCommand("Rückgängig");Check(((Project)typeof(Controller).GetField("p",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(controller)).Folders[0].Songs[0].Year=="2024","Rückgängig umfasst neue Metadatenfelder");
 view.Songs.ClearSelection();view.Songs.CurrentCell=view.Songs.Rows[0].Cells[0];view.Songs.Rows[0].Selected=true;view.InvokeCommand("Abspielen");view.Player.Start.PerformClick();var player=(Playback)typeof(Controller).GetField("playback",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(controller);Check(player.Read().Mode==PlaybackMode.Paused,"Einzelner Wiedergabeknopf pausiert den Player");view.Player.Start.PerformClick();Check(player.Read().Mode==PlaybackMode.Playing,"Einzelner Wiedergabeknopf setzt die Wiedergabe fort");
 foreach(string module in new[]{"Audio-Werkzeuge","Konvertierung","Wiedergabelisten","Statistiken","Cover-Studio","Musikerkennung","Export","Einstellungen"}){Call(controller,"OpenStudioModule",module);Application.DoEvents();Check(view.ModuleHost.Visible&&view.ModuleHost.Controls.Count==1,"Natives Modul startet: "+module);}var state=(Project)typeof(Controller).GetField("p",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(controller);state.Folders.Add(new BoxFolder{Name="001 Weitere Musik",Theme="Weitere Musik",Songs=new List<Song>{state.Folders[0].Songs[0].Copy()}});Call(controller,"Changed","Zweiter Ordner");Call(controller,"RefreshFolders",0);view.Folders.SelectedIndex=1;Application.DoEvents();Check(view.Songs.Rows.Count==1,"Ordneransicht zeigt nur den gewaehlten Ordner");view.Songs.Rows[0].Selected=true;view.Songs.CurrentCell=view.Songs.Rows[0].Cells[0];view.TagEditor.Title.Text="Ordner-Aenderung";Call(controller,"CommitSideTags");view.InvokeCommand("Rückgängig");Application.DoEvents();Check(view.Songs.Rows.Count==1&&((Song)view.Songs.Rows[0].Tag).Title=="4x4xU","Ordneransicht bleibt nach Rueckgaengig mit neuem Projektobjekt gefuellt");state=(Project)typeof(Controller).GetField("p",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(controller);Check(LibraryOperations.Remove(state,new[]{state.Folders[0].Songs[0],state.Folders[1].Songs[0]})==2&&state.Folders[0].Songs.Count==1&&state.Folders[1].Songs.Count==0,"Markierte Titel aus mehreren Ordnern gemeinsam entfernt");Call(controller,"Changed","Mehrere Ordner entfernen");view.InvokeCommand("Rückgängig");view.SelectStudioPage("Bibliothek");Application.DoEvents();Check(view.Player.Visible&&view.TagEditor.Width>=200&&view.Songs.Width>=300,"Player, Seitenleiste und Titelliste bleiben erreichbar");using(var bitmap=new Bitmap(view.Width,view.Height)){view.Refresh();for(int step=0;step<10;step++){Application.DoEvents();System.Threading.Thread.Sleep(20);}using(var graphics=Graphics.FromImage(bitmap))graphics.CopyFromScreen(view.Location,Point.Empty,bitmap.Size);bitmap.Save(Path.Combine(root,"studio-ui.png"));}typeof(Controller).GetField("dirty",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(controller,false);view.Close();}
 Console.WriteLine("BESTANDEN: "+count+" Studio-Integrationsprüfungen; UI unter Mono/Xvfb, keine echte Windows-Mikrofon-/Audioabnahme");}
